import { z } from 'zod';

export const AddEmployeeReviewSchema = z.object({
    employeeName: z.string().min(1, 'اسم الموظف مطلوب'),
    employeeCode: z.string().min(1, 'كود الموظف مطلوب'),
    period: z.string().min(1, 'اختر الفترة التقييمية'),
    quality: z.number().min(0).max(5),
    productivity: z.number().min(0).max(5),
    communication: z.number().min(0).max(5),
    discipline: z.number().min(0).max(5),
    initiative: z.number().min(0).max(5),
    teamwork: z.number().min(0).max(5),
    strengths: z.string().optional(),
    development: z.string().optional(),
    goals: z.string().optional(),
});

export type AddEmployeeReviewFormValues = z.infer<typeof AddEmployeeReviewSchema>;